function validate([words]) {
  if (!Array.isArray(words) || words.length < 1 || words.length > 100000) return 'words needs 1 to 10^5 strings.';
  let total = 0;
  for (const word of words) {
    if (typeof word !== 'string' || word.length < 1 || word.length > 100000) return 'Each word has 1 to 10^5 characters.';
    if (!/^[a-z]+$/.test(word)) return 'Words may contain only lowercase English letters.';
    total += word.length;
  }
  if (total > 500000) return 'The words may have at most 5 * 10^5 characters in total.';
  return null;
}

