function countPrefixSuffixPairs(words) {
  const root = { children: new Map(), ends: 0 };
  let pairs = 0;

  for (const word of words) {
    const n = word.length;
    let node = root;
    for (let k = 0; k < n; k++) {
      const front = word.charCodeAt(k) - 97;
      const back = word.charCodeAt(n - 1 - k) - 97;
      const key = front * 26 + back;
      if (!node.children.has(key)) {
        node.children.set(key, { children: new Map(), ends: 0 });
      }
      node = node.children.get(key);
      pairs += node.ends;
    }
    node.ends++;
  }
  return pairs;
}

