function countPrefixSuffixPairs(words) {
  let total = 0;
  for (let i = 0; i < words.length; i++) {
    for (let j = i + 1; j < words.length; j++) {
      const small = words[i];
      const big = words[j];
      if (small.length > big.length) continue;
      if (big.slice(0, small.length) === small && big.slice(big.length - small.length) === small) total++;
    }
  }
  return total;
}

