function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const randomWord = (length, alphabet) => {
    let text = '';
    for (let i = 0; i < length; i++) text += alphabet[int(0, alphabet.length - 1)];
    return text;
  };
  // A word framed by a shorter piece on both ends, so it has that piece as a border.
  const framed = (piece, alphabet, extra) => (rand() < 0.3 ? piece + piece.slice(int(0, piece.length - 1)) : piece + randomWord(int(0, extra), alphabet) + piece);
  if (size === 'small') {
    const alphabet = ['a', 'ab', 'abc', 'xyz'][int(0, 3)];
    const n = int(1, 8);
    const pool = [randomWord(int(1, 2), alphabet), randomWord(int(1, 3), alphabet)];
    const words = [];
    for (let i = 0; i < n; i++) {
      const roll = rand();
      if (roll < 0.35) words.push(pool[int(0, 1)]);
      else if (roll < 0.7) words.push(framed(pool[int(0, 1)], alphabet, 2));
      else words.push(randomWord(int(1, 6), alphabet));
    }
    return [words];
  }
  const shape = int(0, 3);
  if (shape === 0) {
    return [Array.from({ length: 2000 }, () => 'a'.repeat(int(1, 30)))];
  }
  if (shape === 1) {
    return [Array.from({ length: 2000 }, () => randomWord(int(1, 12), 'ab'))];
  }
  if (shape === 2) {
    const pool = Array.from({ length: 12 }, () => randomWord(int(1, 4), 'abc'));
    const words = [];
    for (let i = 0; i < 2000; i++) {
      const piece = pool[int(0, pool.length - 1)];
      words.push(rand() < 0.3 ? piece : framed(piece, 'abc', 10));
    }
    return [words];
  }
  // A few long periodic words mixed with their short borders.
  const unit = randomWord(int(2, 5), 'xyz');
  const words = [];
  for (let i = 0; i < 200; i++) {
    words.push(rand() < 0.1 ? unit.repeat(int(100, 400)) : unit.repeat(int(1, 6)) + unit.slice(0, int(0, unit.length - 1)));
  }
  return [words];
}
